import limited_client as r, numpy as np
for c in ['topview','behindGripper','gripperPOV']:
 o=r.observe(c); d=o['depth_m']; print(c)
 for u,v in ([(260,150),(260,160),(245,150),(270,145),(200,140)] if c=='topview' else [(250,275),(250,260),(220,220),(260,220),(240,240)]):
  if np.isfinite(d[v,u]) and d[v,u]>0:
   K=o['intrinsic']; ray=np.array([(u-K[0,2])/K[0,0],(v-K[1,2])/K[1,1],1]); p=o['camera_to_world'][:3,:3]@(ray*d[v,u])+o['camera_to_world'][:3,3]; print((u,v),round(d[v,u],3),p.round(3))
